RARE_RE = re.compile(r"\+-|\.\.|\?\?\?\?|!!!!|,,|--")
SCOPED_ABBR_RE = re.compile(r"\((c|tm|r|p)\)", flags=re.IGNORECASE)
def replace_scoped(inlineTokens: list[Token]) -> None:
    inside_autolink = 0
    for token in inlineTokens:
        if token.type == "text" and not inside_autolink:
            token.content = SCOPED_ABBR_RE.sub(replaceFn, token.content)
        if token.type == "link_open" and token.info == "auto":
            inside_autolink -= 1
        if token.type == "link_close" and token.info == "auto":
            inside_autolink += 1
def replace_rare(inlineTokens: list[Token]) -> None:
    inside_autolink = 0
    for token in inlineTokens:
        if token.type == "text" and not inside_autolink:
            if RARE_RE.search(token.content):
                token.content = PLUS_MINUS_RE.sub("±", token.content)
                token.content = ELLIPSIS_RE.sub("…", token.content)
                token.content = ELLIPSIS_QUESTION_EXCLAMATION_RE.sub(
                    "\\1..", token.content
                )
                token.content = QUESTION_EXCLAMATION_RE.sub("\\1\\1\\1", token.content)
                token.content = COMMA_RE.sub(",", token.content)
                token.content = EM_DASH_RE.sub("\\1\u2014", token.content)
                token.content = EN_DASH_RE.sub("\\1\u2013", token.content)
                token.content = EN_DASH_INDENT_RE.sub("\\1\u2013", token.content)
        if token.type == "link_open" and token.info == "auto":
            inside_autolink -= 1
        if token.type == "link_close" and token.info == "auto":
            inside_autolink += 1
def replace(state: StateCore) -> None:
    if not state.md.options.typographer:
        return
    for token in state.tokens:
        if token.type != "inline":
            continue
        if token.children is None:
            continue
        if SCOPED_ABBR_RE.search(token.content):
            replace_scoped(token.children)
        if RARE_RE.search(token.content):
            replace_rare(token.children)
QUOTE_RE = re.compile(r"['\"]")
def process_inlines(tokens: list[Token], state: StateCore) -> None:
    stack: list[dict[str, Any]] = []
    for i in range(len(tokens)):
        token = tokens[i]
        thisLevel = token.level
        j = 0
        for j in range(len(stack))[::-1]:
            if stack[j]["level"] <= thisLevel:
                break
        else:
            j -= 1
        stack = stack[: j + 1]
        if token.type != "text":
            continue
        text = token.content
        pos = 0
        maximum = len(text)
        while pos < maximum:
            goto_outer = False
            lastIndex = pos
            t = QUOTE_RE.search(text[lastIndex:])
            if not t:
                break
            canOpen = canClose = True
            pos = t.start(0) + lastIndex + 1
            isSingle = t.group(0) == "'"
            lastChar = 0x20
            if t.start(0) + lastIndex - 1 >= 0:
                lastChar = charCodeAt(text, t.start(0) + lastIndex - 1)
            else:
                for j in range(i)[::-1]:
                    if tokens[j].type == "softbreak" or tokens[j].type == "hardbreak":
                        break
                    if not tokens[j].content:
                        continue
                    lastChar = charCodeAt(tokens[j].content, len(tokens[j].content) - 1)
                    break
            nextChar = 0x20
            if pos < maximum:
                nextChar = charCodeAt(text, pos)
            else:
                for j in range(i + 1, len(tokens)):
                    if tokens[j].type == "softbreak" or tokens[j].type == "hardbreak":
                        break
                    if not tokens[j].content:
                        continue
                    nextChar = charCodeAt(tokens[j].content, 0)
                    break
            isLastPunctChar = isMdAsciiPunct(lastChar) or isPunctChar(chr(lastChar))
            isNextPunctChar = isMdAsciiPunct(nextChar) or isPunctChar(chr(nextChar))
            isLastWhiteSpace = isWhiteSpace(lastChar)
            isNextWhiteSpace = isWhiteSpace(nextChar)
            if isNextWhiteSpace:
                canOpen = False
            elif isNextPunctChar:
                if not (isLastWhiteSpace or isLastPunctChar):
                    canOpen = False
            if isLastWhiteSpace:
                canClose = False
            elif isLastPunctChar:
                if not (isNextWhiteSpace or isNextPunctChar):
                    canClose = False
            if nextChar == 0x22 and t.group(0) == '"':
                if lastChar >= 0x30 and lastChar <= 0x39:
                    canClose = canOpen = False
            if canOpen and canClose:
                canOpen = isLastPunctChar
                canClose = isNextPunctChar
            if not canOpen and not canClose:
                if isSingle:
                    token.content = replaceAt(
                        token.content, t.start(0) + lastIndex, APOSTROPHE
                    )
                continue
            if canClose:
                for j in range(len(stack))[::-1]:
                    item = stack[j]
                    if stack[j]["level"] < thisLevel:
                        break
                    if item["single"] == isSingle and stack[j]["level"] == thisLevel:
                        item = stack[j]
                        if isSingle:
                            openQuote = state.md.options.quotes[2]
                            closeQuote = state.md.options.quotes[3]
                        else:
                            openQuote = state.md.options.quotes[0]
                            closeQuote = state.md.options.quotes[1]
                        token.content = replaceAt(
                            token.content, t.start(0) + lastIndex, closeQuote
                        )
                        tokens[item["token"]].content = replaceAt(
                            tokens[item["token"]].content, item["pos"], openQuote
                        )
                        pos += len(closeQuote) - 1
                        if item["token"] == i:
                            pos += len(openQuote) - 1
                        text = token.content
                        maximum = len(text)
                        stack = stack[:j]
                        goto_outer = True
                        break
                if goto_outer:
                    goto_outer = False
                    continue
            if canOpen:
                stack.append(
                    {
                        "token": i,
                        "pos": t.start(0) + lastIndex,
                        "single": isSingle,
                        "level": thisLevel,
                    }
                )
            elif canClose and isSingle:
                token.content = replaceAt(
                    token.content, t.start(0) + lastIndex, APOSTROPHE
                )
def smartquotes(state: StateCore) -> None:
    if not state.md.options.typographer:
        return
    for token in state.tokens:
        if token.type != "inline" or not QUOTE_RE.search(token.content):
            continue
        if token.children is not None:
            process_inlines(token.children, state)

def get_minsize(size):
    if "_" not in size:
        return (0, 0)
    min_width = 0
    min_height = 0
    if "x" in size:
        sizes = size.split('x')
        if sizes[0].endswith("_"):
            min_width = int(sizes[0][:-1])
        if sizes[1].endswith("_"):
            min_height = int(sizes[1][:-1])
    elif size.endswith("_"):
        min_width = int(size[:-1])
        min_height = min_width
    return (min_width, min_height)
def get_sizes(size, imgsize):
        raise ThumbnailError('Size %s has errors: crop and minsize cannot be combined.' % size)
def resize_image(image, size):
    image = ImageOps.exif_transpose(image)
    new_size, crop = get_sizes(size, image.size)
    image = image.resize(new_size, resample=Resampling.LANCZOS)
    if crop:
        image = image.crop(crop)
    min_width, min_height = get_minsize(size)
    if min_width > new_size[0] or min_height > new_size[1]:
        padding = math.ceil(max(min_width - new_size[0], min_height - new_size[1]) / 2)
        if image.mode not in ("RGB", "RGBA"):
            image = image.convert('RGB')
        image = ImageOps.expand(image, border=padding, fill="white")
        new_width = max(min_width, new_size[0])
        new_height = max(min_height, new_size[1])
        new_x = (image.width - new_width) // 2
        new_y = (image.height - new_height) // 2
        image = image.crop((new_x, new_y, new_x + new_width, new_y + new_height))
    return image
def create_thumbnail(sourcename, size):
    source = default_storage.open(sourcename)
    image = Image.open(BytesIO(source.read()))
    try:
        image.load()
    except:
        raise ThumbnailError('Could not load image')
    frames = [resize_image(frame, size) for frame in ImageSequence.Iterator(image)]
    image_out = frames[0]
    save_kwargs = {}
    if source.name.lower().endswith('.jpg') or source.name.lower().endswith('.jpeg'):
        target_ext = 'jpeg'
        quality = 95
    elif source.name.lower().endswith('.gif') or source.name.lower().endswith('.png'):
        target_ext = source.name.lower()[-3:]
        quality = None
        image_out.info = image.info
        save_kwargs = {
            'append_images': frames[1:],
            'loop': image.info.get('loop', 0),
            'save_all': True,
        }
    else:
        target_ext = 'png'
        quality = None
    checksum = hashlib.md5(image.tobytes()).hexdigest()
    name = checksum + '.' + size.replace('^', 'c') + '.' + target_ext
    buffer = BytesIO()
    if image_out.mode == "P" and source.name.lower().endswith('.png'):
        image_out = image_out.convert('RGBA')
    if image_out.mode not in ("1", "L", "RGB", "RGBA"):
        image_out = image_out.convert('RGB')
    image_out.save(fp=buffer, format=target_ext.upper(), quality=quality, **save_kwargs)
    imgfile = ContentFile(buffer.getvalue())
    t = Thumbnail.objects.create(source=sourcename, size=size)
    t.thumb.save(name, imgfile)
    return t
