class GlancesActions(object):
    def get(self, stat_name):
        """Get the stat_name criticity."""
        try:
            return self.status[stat_name]
        except KeyError:
            return None
    def set(self, stat_name, criticity):
        """Set the stat_name to criticity."""
        self.status[stat_name] = criticity
    def run(self, stat_name, criticity, commands, repeat, mustache_dict=None):
        """Run the commands (in background).
        - stats_name: plugin_name (+ header)
        - criticity: criticity of the trigger
        - commands: a list of command line with optional {{mustache}}
        - If True, then repeat the action
        - mustache_dict: Plugin stats (can be use within {{mustache}})
        Return True if the commands have been ran.
        """
        if (self.get(stat_name) == criticity and not repeat) or \
           not self.start_timer.finished():
            return False
        logger.debug("{} action {} for {} ({}) with stats {}".format(
            "Repeat" if repeat else "Run",
            commands, stat_name, criticity, mustache_dict))
        for cmd in commands:
            if chevron_tag:
                cmd_full = chevron.render(cmd, mustache_dict)
            else:
                cmd_full = cmd
            logger.info("Action triggered for {} ({}): {}".format(stat_name,
                                                                  criticity,
                                                                  cmd_full))
            try:
                ret = secure_popen(cmd_full)
            except OSError as e:
                logger.error("Action error for {} ({}): {}".format(stat_name,
                                                                   criticity,
                                                                   e))
            else:
                logger.debug("Action result for {} ({}): {}".format(stat_name,
                                                                    criticity,
                                                                    ret))
        self.set(stat_name, criticity)
        return True
def secure_popen(cmd):
    """A more or less secure way to execute system command
    Return: the result of the command OR an error message
    """
    ret = None
    cmd_split_redirect = cmd.split('>')
    if len(cmd_split_redirect) > 2:
        return 'Glances error: Only one file redirection allowed ({})'.format(cmd)
    elif len(cmd_split_redirect) == 2:
        stdout_redirect = cmd_split_redirect[1].strip()
        cmd = cmd_split_redirect[0]
    else:
        stdout_redirect = None
    sub_cmd_stdin = None
    p_last = None
    for sub_cmd in cmd.split('|'):
        sub_cmd_split = [i for i in sub_cmd.split(' ') if i]
        p = Popen(sub_cmd_split,
                  shell=False,
                  stdin=sub_cmd_stdin,
                  stdout=PIPE,
                  stderr=PIPE)
        if p_last is not None:
            p_last.stdout.close()
        p_last = p
        sub_cmd_stdin = p.stdout
    p_ret = p_last.communicate()
    if nativestr(p_ret[1]) == '':
        ret = nativestr(p_ret[0])
        if stdout_redirect is not None:
            with open(stdout_redirect, "w") as stdout_redirect_file:
                stdout_redirect_file.write(ret)
    else:
        ret = nativestr(p_ret[1])
    return ret
class ThreadScanner(threading.Thread):
    def _port_scan_icmp(self, port):
        """Scan the (ICMP) port structure (dict) and update the status key."""
        ret = None
        if WINDOWS:
            timeout_opt = '-w'
            count_opt = '-n'
        elif MACOS or BSD:
            timeout_opt = '-t'
            count_opt = '-c'
        else:
            timeout_opt = '-W'
            count_opt = '-c'
        cmd = ['ping',
               count_opt, '1',
               timeout_opt, str(self._resolv_name(port['timeout'])),
               self._resolv_name(port['host'])]
        fnull = open(os.devnull, 'w')
        try:
            counter = Counter()
            ret = subprocess.check_call(cmd, stdout=fnull, stderr=fnull, close_fds=True)
            if ret == 0:
                port['status'] = counter.get()
            else:
                port['status'] = False
        except subprocess.CalledProcessError as e:
            port['status'] = False
        except Exception as e:
            logger.debug("{}: Error while pinging host {} ({})".format(self.plugin_name, port['host'], e))
        return ret
class GlancesClientBrowser(object):
    def __display_server(self, server):
        """
        Connect and display the given server
        """
        logger.debug("Selected server {}".format(server))
        self.screen.display_popup(
            'Connect to {}:{}'.format(server['name'], server['port']), duration=1)
        if server['password'] is None:
            clear_password = self.password.get_password(server['name'])
            if (clear_password is None or self.get_servers_list()
                    [self.screen.active_server]['status'] == 'PROTECTED'):
                clear_password = self.screen.display_popup(
                    'Password needed for {}: '.format(server['name']), is_input=True)
            if clear_password is not None:
                self.set_in_selected('password', self.password.sha256_hash(clear_password))
        logger.info("Connect Glances client to the {} server".format(server['key']))
        args_server = self.args
        args_server.client = server['ip']
        args_server.port = server['port']
        args_server.username = server['username']
        args_server.password = server['password']
        client = GlancesClient(config=self.config, args=args_server, return_to_browser=True)
        if not client.login():
            self.screen.display_popup(
                "Sorry, cannot connect to '{}'\n"
                "See '{}' for more details".format(server['name'], LOG_FILENAME))
            self.set_in_selected('status', 'OFFLINE')
        else:
            connection_type = client.serve_forever()
            try:
                logger.debug("Disconnect Glances client from the {} server".format(server['key']))
            except IndexError:
                pass
            else:
                if connection_type == 'snmp':
                    self.set_in_selected('status', 'SNMP')
                else:
                    self.set_in_selected('status', 'ONLINE')
        self.screen.active_server = None
class GlancesPassword(object):
    def get_password(self, description='', confirm=False, clear=False):
        """Get the password from a Glances client or server.
        For Glances server, get the password (confirm=True, clear=False):
            1) from the password file (if it exists)
            2) from the CLI
        Optionally: save the password to a file (hashed with salt + SHA-256)
        For Glances client, get the password (confirm=False, clear=True):
            1) from the CLI
            2) the password is hashed with SHA-256 (only SHA string transit
               through the network)
        """
        if os.path.exists(self.password_file) and not clear:
            logger.info("Read password from file {}".format(self.password_file))
            password = self.load_password()
        else:
            password_sha256 = self.sha256_hash(getpass.getpass(description))
            password_hashed = self.hash_password(password_sha256)
            if confirm:
                password_confirm = self.sha256_hash(getpass.getpass('Password (confirm): '))
                if not self.check_password(password_hashed, password_confirm):
                    logger.critical("Sorry, passwords do not match. Exit.")
                    sys.exit(1)
            if clear:
                password = password_sha256
            else:
                password = password_hashed
            if not clear:
                save_input = input('Do you want to save the password? [Yes/No]: ')
                if len(save_input) > 0 and save_input[0].upper() == 'Y':
                    self.save_password(password_hashed)
        return password
class GlancesClient(object):
    def __init__(self, config=None, args=None, timeout=7, return_to_browser=False):
        self.args = args
        self.config = config
        self._quiet = args.quiet
        self._client_mode = 'glances'
        self.return_to_browser = return_to_browser
        if args.password != "":
            self.uri = 'http://{}:{}@{}:{}'.format(args.username, args.password,
                                                   args.client, args.port)
        else:
            self.uri = 'http://{}:{}'.format(args.client, args.port)
        logger.debug("Try to connect to {}".format(self.uri))
        transport = GlancesClientTransport()
        transport.set_timeout(timeout)
        try:
            self.client = ServerProxy(self.uri, transport=transport)
        except Exception as e:
            self.log_and_exit("Client couldn't create socket {}: {}".format(self.uri, e))
class GlancesServer(object):
