def login():
    data = request.get_json()
    if not data:
        data = request.values
    if "user" in data and "pass" in data:
        username = data["user"]
        password = data["pass"]
        if "remember" in data and data["remember"] in valid_boolean_trues:
            remember = True
        else:
            remember = False
        if "usersession.id" in session:
            _logout(current_user)
        user = octoprint.server.userManager.find_user(username)
        if user is not None:
            if octoprint.server.userManager.check_password(username, password):
                if not user.is_active:
                    abort(403)
                user = octoprint.server.userManager.login_user(user)
                session["usersession.id"] = user.session
                session["usersession.signature"] = session_signature(
                    username, user.session
                )
                g.user = user
                login_user(user, remember=remember)
                identity_changed.send(
                    current_app._get_current_object(), identity=Identity(user.get_id())
                )
                session["login_mechanism"] = "http"
                remote_addr = get_remote_address(request)
                logging.getLogger(__name__).info(
                    "Actively logging in user {} from {}".format(
                        user.get_id(), remote_addr
                    )
                )
                response = user.as_dict()
                response["_is_external_client"] = s().getBoolean(
                    ["server", "ipCheck", "enabled"]
                ) and not util_net.is_lan_address(
                    remote_addr,
                    additional_private=s().get(["server", "ipCheck", "trustedSubnets"]),
                )
                response["_login_mechanism"] = session["login_mechanism"]
                r = make_response(jsonify(response))
                r.delete_cookie("active_logout")
                eventManager().fire(
                    Events.USER_LOGGED_IN, payload={"username": user.get_id()}
                )
                return r
        abort(403)
    elif "passive" in data:
        return passive_login()
    abort(400, description="Neither user and pass attributes nor passive flag present")
class UserManager(GroupChangeListener):
    def logout_user(self, user, stale=False):
        if user is None or user.is_anonymous:
            return
        if isinstance(user, LocalProxy):
            user = user._get_current_object()
        if not isinstance(user, SessionUser):
            return
        userid = user.get_id()
        sessionid = user.session
        if userid in self._sessionids_by_userid:
            try:
                self._sessionids_by_userid[userid].remove(sessionid)
            except KeyError:
                pass
        if sessionid in self._session_users_by_session:
            try:
                del self._session_users_by_session[sessionid]
            except KeyError:
                pass
        for listener in self._login_status_listeners:
            try:
                listener.on_user_logged_out(user, stale=stale)
            except Exception:
                self._logger.exception(
                    f"Error in on_user_logged_out on {listener!r}",
                    extra={"callback": fqcn(listener)},
                )
        self._logger.info(f"Logged out user: {user.get_id()}")
    def _cleanup_sessions(self):
        for session, user in list(self._session_users_by_session.items()):
            if not isinstance(user, SessionUser):
                continue
            if user.touched + (15 * 60) < time.monotonic():
                self._logger.info(
                    f"Cleaning up user session {session} for user {user.get_id()}"
                )
                self.logout_user(user, stale=True)
    def validate_user_session(self, userid, session):
        self._cleanup_sessions()
        if session in self._session_users_by_session:
            user = self._session_users_by_session[session]
            return userid == user.get_id()
        return False
    def find_sessions_for(self, matcher):
        self._cleanup_sessions()
        result = []
        for user in self.get_all_users():
            if matcher(user):
                try:
                    session_ids = self._sessionids_by_userid[user.get_id()]
                    for session_id in session_ids:
                        try:
                            session_user = self._session_users_by_session[session_id]
                            session_user.touch()
                            result.append(session_user)
                        except KeyError:
                            continue
                except KeyError:
                    pass
        return result
