def inject_data_into_fs(fs, key, net, metadata, admin_password, execute):
    """Injects data into a filesystem already mounted by the caller.
    Virt connections can call this directly if they mount their fs
    in a different way to inject_data
    """
    if key:
        _inject_key_into_fs(key, fs, execute=execute)
    if net:
        _inject_net_into_fs(net, fs, execute=execute)
    if metadata:
        _inject_metadata_into_fs(metadata, fs, execute=execute)
    if admin_password:
        _inject_admin_password_into_fs(admin_password, fs, execute=execute)
def _inject_metadata_into_fs(metadata, fs, execute=None):
    metadata_path = os.path.join(fs, "meta.js")
    metadata = dict([(m.key, m.value) for m in metadata])
    utils.execute('tee', metadata_path,
                  process_input=jsonutils.dumps(metadata), run_as_root=True)

_is_image_dataurl = re.compile(
    r'^data:image/.+;base64', re.I).search
_is_possibly_malicious_scheme = re.compile(
    r'(?:javascript|jscript|livescript|vbscript|data|about|mocha):',
    re.I).search
def _is_javascript_scheme(s):
    if _is_image_dataurl(s):
        return None
    return _is_possibly_malicious_scheme(s)
class Cleaner(object):
    def _remove_javascript_link(self, link):
        new = _substitute_whitespace('', unquote_plus(link))
        if _is_javascript_scheme(new):
            return ''
        return link

_find_image_dataurls = re.compile(
    r'^data:image/(.+);base64,', re.I).findall
_is_possibly_malicious_scheme = re.compile(
    r'(javascript|jscript|livescript|vbscript|data|about|mocha):',
    re.I).findall
_is_unsafe_image_type = re.compile(r"(xml|svg)", re.I).findall
def _is_javascript_scheme(s):
    is_image_url = False
    for image_type in _find_image_dataurls(s):
        is_image_url = True
        if _is_unsafe_image_type(image_type):
            return True
    if is_image_url:
        return False
    return bool(_is_possibly_malicious_scheme(s))
class Cleaner(object):
    def _remove_javascript_link(self, link):
        new = _substitute_whitespace('', unquote_plus(link))
        if _is_javascript_scheme(new):
            return ''
        return link

