def origin_from_url(url: str) -> str:
    parts = urlparse(url)
    new = [parts[0], parts[1], "", "", "", ""]
    return urlunparse(new)
def allow_redirect_url(url: str) -> bool:
    """
    Check that a redirect target is allowed against the CORS policy.
    The "Cross-Origin Resource Sharing" configuration specifies which external hosts
    are allowed to access Open Forms. We leverage this configuration to block or allow
    redirects to external hosts.
    """
    cors = CorsMiddleware()
    origin = origin_from_url(url)
    parts = urlparse(url)
    if not cors_conf.CORS_ALLOW_ALL_ORIGINS and not cors.origin_found_in_white_lists(
        origin, parts
    ):
        return False
    else:
        return True

class PSFile:
    def readline(self):
        s = self.char or b""
        self.char = None
        c = self.fp.read(1)
        while c not in b"\r\n":
            s = s + c
            c = self.fp.read(1)
        self.char = self.fp.read(1)
        if self.char in b"\r\n":
            self.char = None
        return s.decode("latin-1")
class EpsImageFile(ImageFile.ImageFile):
    def _open(self):
        (length, offset) = self._find_offset(self.fp)
        fp = PSFile(self.fp)
        fp.seek(offset)
        box = None
        self.mode = "RGB"
        self._size = 1, 1
        s_raw = fp.readline()
        s = s_raw.strip("\r\n")
        while s_raw:
            if s:
                if len(s) > 255:
                    raise SyntaxError("not an EPS file")
                try:
                    m = split.match(s)
                except re.error as e:
                    raise SyntaxError("not an EPS file") from e
                if m:
                    k, v = m.group(1, 2)
                    self.info[k] = v
                    if k == "BoundingBox":
                        try:
                            box = [int(float(i)) for i in v.split()]
                            self._size = box[2] - box[0], box[3] - box[1]
                            self.tile = [
                                ("eps", (0, 0) + self.size, offset, (length, box))
                            ]
                        except Exception:
                            pass
                else:
                    m = field.match(s)
                    if m:
                        k = m.group(1)
                        if k == "EndComments":
                            break
                        if k[:8] == "PS-Adobe":
                            self.info[k[:8]] = k[9:]
                        else:
                            self.info[k] = ""
                    elif s[0] == "%":
                        pass
                    else:
                        raise OSError("bad EPS header")
            s_raw = fp.readline()
            s = s_raw.strip("\r\n")
            if s and s[:1] != "%":
                break
        while s[:1] == "%":
            if len(s) > 255:
                raise SyntaxError("not an EPS file")
            if s[:11] == "%ImageData:":
                x, y, bi, mo = s[11:].split(None, 7)[:4]
                if int(bi) != 8:
                    break
                try:
                    self.mode = self.mode_map[int(mo)]
                except ValueError:
                    break
                self._size = int(x), int(y)
                return
            s = fp.readline().strip("\r\n")
            if not s:
                break
        if not box:
            raise OSError("cannot determine EPS bounding box")

class PSFile:
    def readline(self):
        s = [self.char or b""]
        self.char = None
        c = self.fp.read(1)
        while (c not in b"\r\n") and len(c):
            s.append(c)
            c = self.fp.read(1)
        self.char = self.fp.read(1)
        if self.char in b"\r\n":
            self.char = None
        return b"".join(s).decode("latin-1")
