LOG = logging.getLogger(__name__)
@alignviewers_bp.route("/remote/cors/<path:remote_url>", methods=["OPTIONS", "GET"])
def remote_cors(remote_url):
    """Proxy a remote URL.
    Useful to e.g. eliminate CORS issues when the remote site does not
        communicate CORS headers well, as in cloud tracks on figshare for IGV.js.
    Based on code from answers to this thread:
        https://stackoverflow.com/questions/6656363/proxying-to-another-web-service-with-flask/
    """
    resp = requests.request(
        method=request.method,
        url=remote_url,
        headers={key: value for (key, value) in request.headers if key != "Host"},
        data=request.get_data(),
        cookies=request.cookies,
        allow_redirects=True,
    )
    excluded_headers = [
        "content-encoding",
        "content-length",
        "transfer-encoding",
        "connection",
    ]
    headers = [
        (name, value)
        for (name, value) in resp.raw.headers.items()
        if name.lower() not in excluded_headers
    ]
    response = Response(resp.content, resp.status_code, headers)
    return response
@alignviewers_bp.route("/remote/static", methods=["OPTIONS", "GET"])
def remote_static():
    """Stream *large* static files with special requirements."""
    file_path = request.args.get("file") or "."
    if current_user.is_authenticated is False or file_path not in session.get("igv_tracks", []):
        LOG.warning(f"{file_path} not in {session.get('igv_tracks', [])}")
        return abort(403)
    range_header = request.headers.get("Range", None)
    if not range_header and (file_path.endswith(".bam") or file_path.endswith(".cram")):
        return abort(500)
    new_resp = send_file_partial(file_path)
    return new_resp
def parse_byte_range(byte_range):
    """Returns the two numbers in 'bytes=123-456' or throws ValueError.
    The last number or both numbers may be None.
    """
    if byte_range.strip() == "":
        return None, None
    m = BYTE_RANGE_RE.match(byte_range)
    if not m:
        raise ValueError("Invalid byte range %s" % byte_range)
    first, last = [x and int(x) for x in m.groups()]
    if last and last < first:
        raise ValueError("Invalid byte range %s" % byte_range)
    return first, last
def send_file_partial(path):
    range_header = request.headers.get("Range", None)
    if not range_header:
        try:
            return send_file(path)
        except IOError:
            return abort(404, "File not found")
    try:
        byte_range = parse_byte_range(request.headers["Range"])
    except ValueError as error:
        return abort(400, "Invalid byte range")
    first, last = byte_range
    try:
        data = None
        with open(path, "rb") as file_handle:
            fs = os.fstat(file_handle.fileno())
            file_len = fs[6]
            if first >= file_len:
                return abort(416, "Requested Range Not Satisfiable")
            if last is None or last >= file_len:
                last = file_len - 1
            response_length = last - first + 1
            file_handle.seek(first)
            data = file_handle.read(response_length)
    except IOError:
        return abort(404, "File not found")
    resp = Response(data, 206, mimetype=mimetypes.guess_type(path)[0], direct_passthrough=True)
    resp.headers.add("Content-type", "application/octet-stream")
    resp.headers.add("Accept-Ranges", "bytes")
    resp.headers.add("Content-Range", "bytes %s-%s/%s" % (first, last, file_len))
    resp.headers.add("Content-Length", str(response_length))
    return resp

@alignviewers_bp.route("/remote/cors/<path:remote_url>", methods=["OPTIONS", "GET"])
def remote_cors(remote_url):
    """Proxy a remote URL.
    Useful to e.g. eliminate CORS issues when the remote site does not
        communicate CORS headers well, as in cloud tracks on figshare for IGV.js.
    Based on code from answers to this thread:
        https://stackoverflow.com/questions/6656363/proxying-to-another-web-service-with-flask/
    """
    if controllers.check_session_tracks(remote_url) is False:
        return abort(403)
    resp = requests.request(
        method=request.method,
        url=remote_url,
        headers={key: value for (key, value) in request.headers if key != "Host"},
        data=request.get_data(),
        cookies=request.cookies,
        allow_redirects=True,
    )
    excluded_headers = [
        "content-encoding",
        "content-length",
        "transfer-encoding",
        "connection",
    ]
    headers = [
        (name, value)
        for (name, value) in resp.raw.headers.items()
        if name.lower() not in excluded_headers
    ]
    response = Response(resp.content, resp.status_code, headers)
    return response
@alignviewers_bp.route("/remote/static", methods=["OPTIONS", "GET"])
def remote_static():
    """Stream *large* static files with special requirements."""
    file_path = request.args.get("file") or "."
    if controllers.check_session_tracks(file_path) is False:
        return abort(403)
    range_header = request.headers.get("Range", None)
    if not range_header and (file_path.endswith(".bam") or file_path.endswith(".cram")):
        return abort(500)
    new_resp = send_file_partial(file_path)
    return new_resp
def parse_byte_range(byte_range):
    """Returns the two numbers in 'bytes=123-456' or throws ValueError.
    The last number or both numbers may be None.
    """
    if byte_range.strip() == "":
        return None, None
    m = BYTE_RANGE_RE.match(byte_range)
    if not m:
        raise ValueError("Invalid byte range %s" % byte_range)
    first, last = [x and int(x) for x in m.groups()]
    if last and last < first:
        raise ValueError("Invalid byte range %s" % byte_range)
    return first, last
def send_file_partial(path):
    range_header = request.headers.get("Range", None)
    if not range_header:
        try:
            return send_file(path)
        except IOError:
            return abort(404, "File not found")
    try:
        byte_range = parse_byte_range(request.headers["Range"])
    except ValueError as error:
        return abort(400, "Invalid byte range")
    first, last = byte_range
    try:
        data = None
        with open(path, "rb") as file_handle:
            fs = os.fstat(file_handle.fileno())
            file_len = fs[6]
            if first >= file_len:
                return abort(416, "Requested Range Not Satisfiable")
            if last is None or last >= file_len:
                last = file_len - 1
            response_length = last - first + 1
            file_handle.seek(first)
            data = file_handle.read(response_length)
    except IOError:
        return abort(404, "File not found")
    resp = Response(data, 206, mimetype=mimetypes.guess_type(path)[0], direct_passthrough=True)
    resp.headers.add("Content-type", "application/octet-stream")
    resp.headers.add("Accept-Ranges", "bytes")
    resp.headers.add("Content-Range", "bytes %s-%s/%s" % (first, last, file_len))
    resp.headers.add("Content-Length", str(response_length))
    return resp

class Application:
    SOCKTYPES = {
        "tcp": socket.SOCK_STREAM,
        "udp": socket.SOCK_DGRAM,
    }
    def __await_reply(self, pr, rsocks, wsocks, timeout):
        extra = 0
        read_buffers = {}
        while (timeout + extra) > time.time():
            if not wsocks and not rsocks:
                break
            r, w, x = select.select(rsocks, wsocks, rsocks + wsocks,
                                    (timeout + extra) - time.time())
            for sock in x:
                sock.close()
                try:
                    rsocks.remove(sock)
                except ValueError:
                    pass
                try:
                    wsocks.remove(sock)
                except ValueError:
                    pass
            for sock in w:
                try:
                    if self.sock_type(sock) == socket.SOCK_DGRAM:
                        sock.sendall(pr.request[4:])
                    else:
                        sock.sendall(pr.request)
                        extra = 10
                except Exception:
                    logging.exception('Error in recv() of %s', sock)
                    continue
                rsocks.append(sock)
                wsocks.remove(sock)
            for sock in r:
                try:
                    reply = self.__handle_recv(sock, read_buffers)
                except Exception:
                    logging.exception('Error in recv() of %s', sock)
                    if self.sock_type(sock) == socket.SOCK_STREAM:
                        rsocks.remove(sock)
                else:
                    if reply is not None:
                        return reply
        return None
    def __handle_recv(self, sock, read_buffers):
        if self.sock_type(sock) == socket.SOCK_DGRAM:
            reply = sock.recv(1048576)
            reply = struct.pack("!I", len(reply)) + reply
            return reply
        else:
            buf = read_buffers.get(sock)
            part = sock.recv(1048576)
            if buf is None:
                if len(part) > 4:
                    (length, ) = struct.unpack("!I", part[0:4])
                    if length + 4 == len(part):
                        return part
                read_buffers[sock] = buf = io.BytesIO()
            if part:
                buf.write(part)
                return None
            else:
                read_buffers.pop(sock)
                reply = buf.getvalue()
                return reply
    def sock_type(self, sock):
        try:
            return sock.type & ~socket.SOCK_NONBLOCK
        except AttributeError:
            return sock.type
    def __call__(self, env, start_response):
        try:
            method = env["REQUEST_METHOD"].upper()
            if method != "POST":
                raise HTTPException(405, "Method not allowed (%s)." % method)
            try:
                length = int(env["CONTENT_LENGTH"])
            except AttributeError:
                length = -1
            try:
                pr = codec.decode(env["wsgi.input"].read(length))
            except codec.ParsingError as e:
                raise HTTPException(400, e.message)
            servers = self.__resolver.lookup(
                pr.realm,
                kpasswd=isinstance(pr, codec.KPASSWDProxyRequest)
            )
            if not servers:
                raise HTTPException(503, "Can't find remote (%s)." % pr)
            reply = None
            wsocks = []
            rsocks = []
            for server in map(urlparse.urlparse, servers):
                scheme = server.scheme.lower().split("+", 1)
                if scheme[0] not in ("kerberos", "kpasswd"):
                    continue
                if len(scheme) > 1 and scheme[1] not in ("tcp", "udp"):
                    continue
                try:
                    port = server.port
                    if port is None:
                        port = scheme[0]
                    addrs = socket.getaddrinfo(server.hostname, port)
                except socket.gaierror:
                    continue
                addrs = tuple(sorted(filter(self.__filter_addr, addrs)))
                for addr in addrs + (None,):
                    if addr is not None:
                        if (len(scheme) > 1
                                and addr[1] != self.SOCKTYPES[scheme[1]]):
                            continue
                        sock = socket.socket(*addr[:3])
                        sock.setblocking(0)
                        try:
                            sock.connect(addr[4])
                        except socket.error as e:
                            if e.errno != 115:
                                sock.close()
                                continue
                        except io.BlockingIOError:
                            pass
                        wsocks.append(sock)
                    for sock in tuple(rsocks):
                        if self.sock_type(sock) == socket.SOCK_DGRAM:
                            wsocks.append(sock)
                            rsocks.remove(sock)
                    timeout = time.time() + (15 if addr is None else 2)
                    reply = self.__await_reply(pr, rsocks, wsocks, timeout)
                    if reply is not None:
                        break
                if reply is not None:
                    break
            for sock in rsocks + wsocks:
                sock.close()
            if reply is None:
                raise HTTPException(503, "Remote unavailable (%s)." % pr)
            raise HTTPException(200, codec.encode(reply),
                                [("Content-Type", "application/kerberos")])
        except HTTPException as e:
            start_response(str(e), e.headers)
            return [e.message]

