class IdToken(OpenIDSchema):
    def verify(self, **kwargs):
        super(IdToken, self).verify(**kwargs)
        try:
            if kwargs["iss"] != self["iss"]:
                raise IssuerMismatch("{} != {}".format(kwargs["iss"], self["iss"]))
        except KeyError:
            pass
        if "aud" in self:
            if "client_id" in kwargs:
                if kwargs["client_id"] not in self["aud"]:
                    raise NotForMe(
                        "{} not in aud:{}".format(kwargs["client_id"], self["aud"]),
                        self,
                    )
            if len(self["aud"]) > 1:
                if "azp" not in self:
                    raise VerificationError("azp missing", self)
                if self["azp"] not in self["aud"]:
                    raise VerificationError("Mismatch between azp and aud claims", self)
        if "azp" in self:
            if "client_id" in kwargs:
                if kwargs["client_id"] != self["azp"]:
                    raise NotForMe(
                        "{} != azp:{}".format(kwargs["client_id"], self["azp"]), self
                    )
        _now = time_util.utc_time_sans_frac()
        try:
            _skew = kwargs["skew"]
        except KeyError:
            _skew = 0
        try:
            _exp = self["exp"]
        except KeyError:
            raise MissingRequiredAttribute("exp")
        else:
            if (_now - _skew) > _exp:
                raise EXPError("Invalid expiration time")
        try:
            _storage_time = kwargs["nonce_storage_time"]
        except KeyError:
            _storage_time = NONCE_STORAGE_TIME
        try:
            _iat = self["iat"]
        except KeyError:
            raise MissingRequiredAttribute("iat")
        else:
            if (_iat + _storage_time) < (_now - _skew):
                raise IATError("Issued too long ago")
            if _now < (_iat - _skew):
                raise IATError("Issued in the future")
        if _exp < _iat:
            raise EXPError("Invalid expiration time")
        return True

def _parse_kwargs(call_expr, context):
    from vyper.codegen.expr import Expr
    def _bool(x):
        assert x.value in (0, 1), "type checker missed this"
        return bool(x.value)
    call_kwargs = {kw.arg: Expr(kw.value, context).ir_node for kw in call_expr.keywords}
    ret = _CallKwargs(
        value=unwrap_location(call_kwargs.pop("value", IRnode(0))),
        gas=unwrap_location(call_kwargs.pop("gas", IRnode("gas"))),
        skip_contract_check=_bool(call_kwargs.pop("skip_contract_check", IRnode(0))),
        default_return_value=call_kwargs.pop("default_return_value", None),
    )
    if len(call_kwargs) != 0:
        raise TypeCheckFailure(f"Unexpected keyword arguments: {call_kwargs}")
    return ret
def _external_call_helper(contract_address, args_ir, call_kwargs, call_expr, context):
    fn_type = call_expr.func._metadata["type"]
    assert fn_type.min_arg_count <= len(args_ir) <= fn_type.max_arg_count
    ret = ["seq"]
    buf, arg_packer, args_ofst, args_len = _pack_arguments(fn_type, args_ir, context)
    ret_unpacker, ret_ofst, ret_len = _unpack_returndata(
        buf, fn_type, call_kwargs, contract_address, context, call_expr
    )
    ret += arg_packer
    if fn_type.return_type is None and not call_kwargs.skip_contract_check:
        ret.append(_extcodesize_check(contract_address))
    gas = call_kwargs.gas
    value = call_kwargs.value
    use_staticcall = fn_type.mutability in (StateMutability.VIEW, StateMutability.PURE)
    if context.is_constant():
        assert use_staticcall, "typechecker missed this"
    if use_staticcall:
        call_op = ["staticcall", gas, contract_address, args_ofst, args_len, buf, ret_len]
    else:
        call_op = ["call", gas, contract_address, value, args_ofst, args_len, buf, ret_len]
    ret.append(check_external_call(call_op))
    return_t = None
    if fn_type.return_type is not None:
        return_t = new_type_to_old_type(fn_type.return_type)
        ret.append(ret_unpacker)
    return IRnode.from_list(ret, typ=return_t, location=MEMORY)
def ir_for_external_call(call_expr, context):
    from vyper.codegen.expr import Expr
    contract_address = Expr.parse_value_expr(call_expr.func.value, context)
    assert isinstance(contract_address.typ, InterfaceType)
    args_ir = [Expr(x, context).ir_node for x in call_expr.args]
    call_kwargs = _parse_kwargs(call_expr, context)
    with contract_address.cache_when_complex("external_contract") as (b1, contract_address):
        return b1.resolve(
            _external_call_helper(contract_address, args_ir, call_kwargs, call_expr, context)
        )
MEMORY = AddrSpace("memory", 32, "mload", "mstore")

TRANSACTION_CONCURRENCY_LIMIT = 10
logger = logging.getLogger(__name__)
received_pdus_counter = Counter("synapse_federation_server_received_pdus", "")
class FederationServer(FederationBase):
    @defer.inlineCallbacks
    @log_function
    def on_incoming_transaction(self, transaction_data):
        request_time = self._clock.time_msec()
        transaction = Transaction(**transaction_data)
        if not transaction.transaction_id:
            raise Exception("Transaction missing transaction_id")
        if not transaction.origin:
            raise Exception("Transaction missing origin")
        logger.debug("[%s] Got transaction", transaction.transaction_id)
        with (yield self._transaction_linearizer.queue(
                (transaction.origin, transaction.transaction_id),
        )):
            result = yield self._handle_incoming_transaction(
                transaction, request_time,
            )
        defer.returnValue(result)
    @defer.inlineCallbacks
    def _handle_incoming_transaction(self, transaction, request_time):
        """ Process an incoming transaction and return the HTTP response
        Args:
            transaction (Transaction): incoming transaction
            request_time (int): timestamp that the HTTP request arrived at
        Returns:
            Deferred[(int, object)]: http response code and body
        """
        response = yield self.transaction_actions.have_responded(transaction)
        if response:
            logger.debug(
                "[%s] We've already responded to this request",
                transaction.transaction_id
            )
            defer.returnValue(response)
            return
        logger.debug("[%s] Transaction is new", transaction.transaction_id)
        received_pdus_counter.inc(len(transaction.pdus))
        origin_host, _ = parse_server_name(transaction.origin)
        pdus_by_room = {}
        for p in transaction.pdus:
            if "unsigned" in p:
                unsigned = p["unsigned"]
                if "age" in unsigned:
                    p["age"] = unsigned["age"]
            if "age" in p:
                p["age_ts"] = request_time - int(p["age"])
                del p["age"]
            event = event_from_pdu_json(p)
            room_id = event.room_id
            pdus_by_room.setdefault(room_id, []).append(event)
        pdu_results = {}
        @defer.inlineCallbacks
        def process_pdus_for_room(room_id):
            logger.debug("Processing PDUs for %s", room_id)
            try:
                yield self.check_server_matches_acl(origin_host, room_id)
            except AuthError as e:
                logger.warn(
                    "Ignoring PDUs for room %s from banned server", room_id,
                )
                for pdu in pdus_by_room[room_id]:
                    event_id = pdu.event_id
                    pdu_results[event_id] = e.error_dict()
                return
            for pdu in pdus_by_room[room_id]:
                event_id = pdu.event_id
                try:
                    yield self._handle_received_pdu(
                        transaction.origin, pdu
                    )
                    pdu_results[event_id] = {}
                except FederationError as e:
                    logger.warn("Error handling PDU %s: %s", event_id, e)
                    pdu_results[event_id] = {"error": str(e)}
                except Exception as e:
                    f = failure.Failure()
                    pdu_results[event_id] = {"error": str(e)}
                    logger.error(
                        "Failed to handle PDU %s: %s",
                        event_id, f.getTraceback().rstrip(),
                    )
        yield concurrently_execute(
            process_pdus_for_room, pdus_by_room.keys(),
            TRANSACTION_CONCURRENCY_LIMIT,
        )
        if hasattr(transaction, "edus"):
            for edu in (Edu(**x) for x in transaction.edus):
                yield self.received_edu(
                    transaction.origin,
                    edu.edu_type,
                    edu.content
                )
        response = {
            "pdus": pdu_results,
        }
        logger.debug("Returning: %s", str(response))
        yield self.transaction_actions.set_response(
            transaction,
            200, response
        )
        defer.returnValue((200, response))
    @defer.inlineCallbacks
    def on_make_join_request(self, origin, room_id, user_id, supported_versions):
